-- ============================================
-- LUMA — Thème 2 : LONG 1/3 x4 — Un date qui évolue sur toute une soirée
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex", "waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "Here we are! I booked us a table at the rooftop bar first, hope that''s okay.", "text_fr": "Nous y voilà ! J''ai réservé une table au bar sur le toit d''abord, j''espère que ça va.", "choices": [{"text": "That''s perfect, I love rooftop bars.", "text_fr": "C''est parfait, j''adore les bars sur les toits.", "next": "n2"}, {"text": "Sounds great, though I''m a bit nervous about heights, ha.", "text_fr": "Ça a l''air super, même si j''ai un peu le vertige, ha.", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "Welcome! What can I get you both to start?", "text_fr": "Bienvenue ! Je vous sers quoi pour commencer tous les deux ?", "choices": [{"text": "I''ll have a mojito, please.", "text_fr": "Je vais prendre un mojito, s''il vous plaît.", "next": "n3"}, {"text": "Just a sparkling water for now, thanks.", "text_fr": "Juste une eau pétillante pour l''instant, merci.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "Don''t worry, we''re not too high up, and the view is worth it!", "text_fr": "T''inquiète, on n''est pas trop haut, et la vue vaut le coup !", "choices": [{"text": "Okay, I''ll trust you on this.", "text_fr": "D''accord, je te fais confiance là-dessus.", "next": "n3"}]}, "n3": {"speaker": "alex", "text": "So, this is officially our first date outside of texting. How''s it feel?", "text_fr": "Donc, c''est officiellement notre premier date en dehors des textos. Ça fait quoi ?", "choices": [{"text": "Honestly, better than I imagined.", "text_fr": "Honnêtement, mieux que ce que j''imaginais.", "next": "n4"}, {"text": "A little surreal, but in a good way!", "text_fr": "Un peu surréaliste, mais dans le bon sens !", "next": "n4"}]}, "n4": {"speaker": "alex", "text": "Ready to head to dinner? I made a reservation nearby.", "text_fr": "Prêt(e) à aller dîner ? J''ai fait une réservation pas loin.", "choices": [{"text": "Absolutely, I''m curious where you picked.", "text_fr": "Carrément, je suis curieux de savoir où tu as choisi.", "next": "n5"}, {"text": "Sounds great, lead the way!", "text_fr": "Ça a l''air super, montre le chemin !", "next": "n5"}]}, "n5": {"speaker": "waiter", "text": "Table for two? Right this way, please.", "text_fr": "Table pour deux ? Par ici, s''il vous plaît.", "choices": [{"text": "Thank you, this place looks lovely.", "text_fr": "Merci, cet endroit a l''air adorable.", "next": "n6"}]}, "n6": {"speaker": "alex", "text": "I found this place a few months ago, it''s become one of my favorites.", "text_fr": "J''ai trouvé cet endroit il y a quelques mois, c''est devenu l''un de mes préférés.", "choices": [{"text": "I can see why, the atmosphere is really nice.", "text_fr": "Je comprends pourquoi, l''ambiance est vraiment sympa.", "next": "n7"}, {"text": "What do you usually order here?", "text_fr": "Tu commandes quoi habituellement ici ?", "next": "n7b"}]}, "n7": {"speaker": "alex", "text": "Right? So, tell me — what''s something you''re really passionate about?", "text_fr": "Hein ? Alors, dis-moi — c''est quoi quelque chose qui te passionne vraiment ?", "choices": [{"text": "Photography, actually. I love capturing little moments.", "text_fr": "La photographie, en fait. J''adore capturer des petits moments.", "next": "n8"}, {"text": "Cooking — I could talk about food forever.", "text_fr": "La cuisine — je pourrais parler de nourriture pour toujours.", "next": "n8b"}]}, "n7b": {"speaker": "alex", "text": "Their risotto is incredible, I always get that.", "text_fr": "Leur risotto est incroyable, je prends toujours ça.", "choices": [{"text": "I''ll trust your recommendation then.", "text_fr": "Je vais te faire confiance alors.", "next": "n8"}]}, "n8": {"speaker": "alex", "text": "That''s amazing, I''d love to see some of your photos sometime.", "text_fr": "C''est génial, j''aimerais voir certaines de tes photos un jour.", "choices": [{"text": "I''d love to show you, actually.", "text_fr": "J''adorerais te les montrer, en fait.", "next": "n9"}]}, "n8b": {"speaker": "alex", "text": "Oh, I love that! What''s your specialty dish?", "text_fr": "Oh, j''adore ça ! C''est quoi ton plat signature ?", "choices": [{"text": "A homemade lasagna, my grandmother''s recipe.", "text_fr": "Une lasagne maison, la recette de ma grand-mère.", "next": "n9"}]}, "n9": {"speaker": "waiter", "text": "How is everything so far? Ready to order your main course?", "text_fr": "Comment ça se passe jusque-là ? Prêts à commander vos plats principaux ?", "choices": [{"text": "Yes, I think I''ll try the risotto.", "text_fr": "Oui, je pense que je vais essayer le risotto.", "next": "n10"}, {"text": "I''ll go with the salmon, please.", "text_fr": "Je vais prendre le saumon, s''il vous plaît.", "next": "n10"}]}, "n10": {"speaker": "alex", "text": "That was delicious. Want to take a walk before we call it a night?", "text_fr": "C''était délicieux. Tu veux faire une promenade avant qu''on se dise bonne nuit ?", "choices": [{"text": "I''d love that, it''s a beautiful evening.", "text_fr": "J''adorerais, c''est une belle soirée.", "next": "n11"}, {"text": "Sure! Actually, I know a nice spot by the river.", "text_fr": "Bien sûr ! En fait, je connais un bel endroit près de la rivière.", "next": "n11b"}]}, "n11": {"speaker": "alex", "text": "(You walk together, the conversation flowing easily under the streetlights.)", "text_fr": "(Vous marchez ensemble, la conversation coule facilement sous les lampadaires.)", "choices": [{"text": "This has honestly been one of my favorite nights in a while.", "text_fr": "Ça a honnêtement été l''une de mes meilleures soirées depuis un moment.", "next": "n12"}, {"text": "(It starts to lightly rain, unexpectedly.)", "text_fr": "(Il commence à pleuvoir légèrement, de façon inattendue.)", "next": "n12b"}]}, "n11b": {"speaker": "alex", "text": "I love that idea, lead the way.", "text_fr": "J''adore cette idée, montre le chemin.", "choices": [{"text": "(You arrive at a quiet spot with a view of the water.)", "text_fr": "(Vous arrivez à un endroit tranquille avec vue sur l''eau.)", "next": "n12"}]}, "n12": {"speaker": "alex", "text": "Me too, honestly. I wasn''t expecting to connect with someone like this.", "text_fr": "Moi aussi, honnêtement. Je m''attendais pas à me connecter avec quelqu''un comme ça.", "choices": [{"text": "Same here — this feels really genuine.", "text_fr": "Pareil pour moi — ça semble vraiment sincère.", "next": "n13"}]}, "n12b": {"speaker": "alex", "text": "(Laughs) Of course it starts raining now! Should we run for cover?", "text_fr": "(Rit) Bien sûr qu''il se met à pleuvoir maintenant ! On court se mettre à l''abri ?", "choices": [{"text": "Let''s just stay a bit, I don''t mind getting a little wet.", "text_fr": "Restons un peu, ça me dérange pas d''être un peu mouillé.", "next": "n13b"}, {"text": "Yeah, let''s find shelter, laughing the whole way.", "text_fr": "Ouais, trouvons un abri, en riant tout le long.", "next": "n13c"}]}, "n13": {"speaker": "alex", "text": "I feel the same. I don''t want tonight to end, honestly.", "text_fr": "Je ressens pareil. Je veux pas que ce soir se termine, honnêtement.", "choices": [{"text": "Neither do I. Maybe we don''t have to just yet.", "text_fr": "Moi non plus. On n''est peut-être pas obligés tout de suite.", "next": "n14"}]}, "n13b": {"speaker": "alex", "text": "(Smiles, standing in the light rain together, a quiet moment forms.)", "text_fr": "(Sourit, debout sous la pluie légère ensemble, un moment tranquille se crée.)", "choices": [{"text": "This is oddly one of the most romantic moments I''ve had.", "text_fr": "C''est étrangement l''un des moments les plus romantiques que j''aie vécus.", "next": "n14"}]}, "n13c": {"speaker": "alex", "text": "(You both duck under an awning, breathless and laughing.)", "text_fr": "(Vous vous réfugiez tous les deux sous un auvent, essoufflés et riant.)", "choices": [{"text": "Well, that was unexpected but fun!", "text_fr": "Bon, c''était inattendu mais fun !", "next": "n14"}]}, "n14": {"speaker": "alex", "text": "So... I don''t really want this night to end. Want to grab a late dessert somewhere?", "text_fr": "Donc... je veux vraiment pas que cette soirée se termine. Tu veux prendre un dessert tardif quelque part ?", "choices": [{"text": "Absolutely, let''s keep this going.", "text_fr": "Absolument, continuons comme ça.", "next": "end_extended"}, {"text": "I''d love to, but I should probably head home — this was perfect though.", "text_fr": "J''adorerais, mais je devrais rentrer — c''était parfait quand même.", "next": "end_perfect"}]}, "end_extended": {"speaker": "alex", "text": "I know just the place. Best decision of the night, honestly.", "text_fr": "Je connais l''endroit parfait. Meilleure décision de la soirée, honnêtement.", "end": true, "ending_label": "Une soirée qui ne veut pas se terminer 🌙✨"}, "end_perfect": {"speaker": "alex", "text": "I completely understand. This was honestly perfect just as it was.", "text_fr": "Je comprends totalement. C''était honnêtement parfait tel quel.", "end": true, "ending_label": "Une soirée parfaite, qui se termine au bon moment 💫"}}}'::jsonb, is_playable = true
where title = 'Un date qui évolue sur toute une soirée'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
